text(await tools.exec_command({cmd:"cat > exposed/src/lib/domain/models/declaration_resolution.rs <<'RS'
//! Identity decisions and payment attribution from checked cleaned evidence.

use std::collections::{BTreeMap, BTreeSet};
use serde::{Deserialize, Serialize};
use super::{declaration_cleaning::{FunderObservationId, FundingEntryId, FunderRole}, entity_ingestion::EntityIngestionError};

pub(crate) const POLICY_VERSION: &str = "funder-resolution-v1";
pub(crate) const AUTOMATIC_THRESHOLD: f64 = 0.999;

#[derive(Clone, Debug, Deserialize)]
pub(crate) struct Observation {
    pub funder_id: FunderObservationId,
    pub member_id: String,
    pub declaration_id: u32,
    pub register_id: u32,
    pub role: FunderRole,
    pub source_scope: String,
    pub source_pointer: String,
    pub funding_entry_id: Option<FundingEntryId>,
    pub funding_ordinal: Option<u32>,
    pub donor_kind: Option<String>,
    pub donor_company_number: Option<String>,
    pub name_normalized: Option<String>,
    pub address_normalized: Option<String>,
}

#[derive(Clone, Debug, Deserialize)]
pub(crate) struct Payment {
    pub funding_entry_id: FundingEntryId,
    pub member_id: String,
    pub parliament_member_id: u32,
    pub declaration_id: u32,
    pub register_id: u32,
    pub funding_ordinal: u32,
    pub parent_declaration_id: Option<u32>,
    pub is_ultimate_payer_different: Option<bool>,
    pub donor_funder_id: Option<FunderObservationId>,
    pub payer_funder_id: Option<FunderObservationId>,
    pub ultimate_payer_funder_id: Option<FunderObservationId>,
}

/// Cleaned evidence whose identity and role references have been checked together.
pub struct ResolutionInput {
    pub(crate) observations: BTreeMap<FunderObservationId, Observation>,
    pub(crate) payments: BTreeMap<FundingEntryId, Payment>,
    pub(crate) digests: BTreeMap<String, String>,
}

fn invalid(message: impl Into<String>) -> EntityIngestionError {
    EntityIngestionError::DataError(message.into())
}

impl ResolutionInput {
    pub(crate) fn new(observations: Vec<Observation>, payments: Vec<Payment>, digests: BTreeMap<String,String>) -> Result<Self, EntityIngestionError> {
        let mut input = Self { observations: BTreeMap::new(), payments: BTreeMap::new(), digests };
        let mut members = BTreeMap::new();
        let mut declarations = BTreeMap::new();
        for payment in payments {
            if payment.declaration_id == 0 || payment.register_id == 0 || payment.parliament_member_id == 0 {
                return Err(invalid("zero cleaned declaration identity"));
            }
            if members.insert(payment.member_id.clone(), payment.parliament_member_id).is_some_and(|id| id != payment.parliament_member_id) {
                return Err(invalid("member identity disagrees between cleaned occurrences"));
            }
            let metadata = (payment.register_id, payment.parent_declaration_id);
            if declarations.insert((payment.member_id.clone(), payment.declaration_id), metadata).is_some_and(|old| old != metadata) {
                return Err(invalid("declaration metadata disagrees between cleaned occurrences"));
            }
            let expected = format!("{}/{}/{}/funding/{}", payment.member_id, payment.declaration_id, payment.register_id, payment.funding_ordinal);
            if serde_json::to_value(&payment.funding_entry_id).map_err(|e| invalid(e.to_string()))? != expected {
                return Err(invalid("funding occurrence ID disagrees with its source identity"));
            }
            if input.payments.insert(payment.funding_entry_id.clone(), payment).is_some() { return Err(invalid("duplicate funding occurrence ID")); }
        }
        for observation in observations {
            if uuid::Uuid::parse_str(&observation.member_id).map_or(true, |id| id.is_nil()) || observation.declaration_id == 0 || observation.register_id == 0 {
                return Err(invalid("invalid cleaned observation identity"));
            }
            let root = root_scope(&observation.source_pointer);
            if !root { return Err(invalid("malformed cleaned source pointer")); }
            match (observation.source_scope.as_str(), &observation.funding_entry_id, observation.funding_ordinal) {
                ("declaration", None, None) if is_root(&observation.source_pointer) => {},
                ("funding_entry", Some(id), Some(ordinal)) => {
                    let payment = input.payments.get(id).ok_or_else(|| invalid("observation has a dangling funding occurrence"))?;
                    if payment.member_id != observation.member_id || payment.declaration_id != observation.declaration_id || payment.register_id != observation.register_id || payment.funding_ordinal != ordinal {
                        return Err(invalid("observation scope disagrees with funding occurrence"));
                    }
                },
                _ => return Err(invalid("invalid observation source scope")),
            }
            if observation.role != FunderRole::Donor && (observation.donor_kind.is_some() || observation.donor_company_number.is_some()) {
                return Err(invalid("payer role carries donor metadata"));
            }
            if observation.name_normalized.as_ref().is_some_and(|name| name.trim().is_empty()) || observation.address_normalized.as_ref().is_some_and(|address| address.trim().is_empty()) {
                return Err(invalid("empty normalized comparison evidence"));
            }
            if let Some((register, _)) = declarations.get(&(observation.member_id.clone(), observation.declaration_id)) {
                if *register != observation.register_id { return Err(invalid("observation register disagrees with declaration")); }
            }
            if input.observations.insert(observation.funder_id.clone(), observation).is_some() { return Err(invalid("duplicate funder observation ID")); }
        }
        for payment in input.payments.values() {
            for (id, role) in [(&payment.donor_funder_id, FunderRole::Donor), (&payment.payer_funder_id,FunderRole::Payer), (&payment.ultimate_payer_funder_id,FunderRole::UltimatePayer)] {
                if let Some(id) = id {
                    let observation = input.observations.get(id).ok_or_else(|| invalid("dangling payment role reference"))?;
                    if observation.role != role || observation.funding_entry_id.as_ref() != Some(&payment.funding_entry_id) { return Err(invalid("payment role points to unrelated observation")); }
                }
            }
        }
        for observation in input.observations.values() {
            if let Some(id) = &observation.funding_entry_id {
                let payment = &input.payments[id];
                let role_id = match observation.role { FunderRole::Donor => &payment.donor_funder_id, FunderRole::Payer => &payment.payer_funder_id, FunderRole::UltimatePayer => &payment.ultimate_payer_funder_id };
                if role_id.as_ref() != Some(&observation.funder_id) { return Err(invalid("unreferenced funding role observation")); }
            }
        }
        Ok(input)
    }

    /// Groups repeated feature profiles without asserting that they identify the same funder.
    #[must_use]
    pub fn scoring_input(&self, candidate_budget: usize) -> ScoringInput {
        let mut groups = BTreeMap::<(String,Option<String>), Vec<FunderObservationId>>::new();
        for observation in self.observations.values() {
            if let Some(name) = &observation.name_normalized {
                groups.entry((name.clone(), observation.address_normalized.clone())).or_default().push(observation.funder_id.clone());
            }
        }
        let mut rows = Vec::new();
        let mut members = BTreeMap::new();
        for (index, ((name,address), ids)) in groups.into_iter().enumerate() {
            let key = format!("profile-{index:08}");
            rows.push(ComparisonRow { key: key.clone(), name: name.clone(), address: address.clone() });
            members.insert(key.clone(), ids.clone());
            if ids.len() > 1 {
                let copy = format!("{key}-repeat");
                rows.push(ComparisonRow { key: copy.clone(), name, address });
                members.insert(copy, ids);
            }
        }
        ScoringInput { version: 1, candidate_budget, rows, members }
    }
}

fn root_scope(pointer: &str) -> bool {
    let parts = pointer.split('/').collect::<Vec<_>>();
    parts.len() >= 4 && parts[0].is_empty() && parts[1] == "versions" && parts[2].parse::<u32>().is_ok() && parts[3] == "fields"
        && (parts.len() - 4).is_multiple_of(3)
        && parts[4..].chunks(3).all(|chunk| chunk[0].parse::<u32>().is_ok() && chunk[1] == "values" && chunk[2].parse::<u32>().is_ok())
}
fn is_root(pointer: &str) -> bool { pointer.split('/').count() == 4 }

/// Versioned feature rows supplied to the external statistical scorer.
#[derive(Serialize)]
pub struct ScoringInput {
    pub(crate) version: u32,
    pub(crate) candidate_budget: usize,
    pub(crate) rows: Vec<ComparisonRow>,
    #[serde(skip)]
    members: BTreeMap<String, Vec<FunderObservationId>>,
}
#[derive(Serialize)]
pub(crate) struct ComparisonRow { pub key: String, pub name: String, pub address: Option<String> }

/// Validated model scores, with provenance supplied by the scoring runtime.
pub struct ScoredPairs {
    pub(crate) pairs: Vec<ScoredPair>,
    pub(crate) model: serde_json::Value,
}
#[derive(Deserialize)]
pub(crate) struct ScoredPair {
    pub left: String, pub right: String, pub probability: f64,
    pub name_level: i32, pub address_level: i32,
}
impl ScoredPairs {
    pub(crate) fn checked(pairs: Vec<ScoredPair>, model: serde_json::Value, input: &ScoringInput) -> Result<Self, EntityIngestionError> {
        let mut seen = BTreeSet::new();
        if pairs.len() > input.candidate_budget { return Err(invalid("worker exceeded candidate budget")); }
        for pair in &pairs {
            if pair.left >= pair.right || !input.members.contains_key(&pair.left) || !input.members.contains_key(&pair.right) || !seen.insert((&pair.left,&pair.right)) {
                return Err(invalid("worker returned duplicate, unordered, or unknown profile pair"));
            }
            if !pair.probability.is_finite() || !(0.0..=1.0).contains(&pair.probability) || !(-1..=2).contains(&pair.name_level) || !(-1..=1).contains(&pair.address_level) {
                return Err(invalid("worker returned invalid probability or comparison level"));
            }
        }
        Ok(Self { pairs, model })
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum EntityKind { Person, Organisation, Unknown }
fn kind(observation: &Observation) -> EntityKind {
    match observation.donor_kind.as_deref().map(str::trim).map(str::to_ascii_lowercase).as_deref() {
        Some("individual" | "person") => EntityKind::Person,
        Some("company" | "charity" | "trade union" | "union" | "other organisation" | "organisation" | "unincorporated association") => EntityKind::Organisation,
        _ => EntityKind::Unknown,
    }
}
fn company(observation: &Observation) -> Option<String> {
    if observation.donor_kind.as_deref().is_some_and(|kind| !kind.trim().eq_ignore_ascii_case("company")) { return None; }
    let number = observation.donor_company_number.as_ref()?.trim_matches(|c: char| c.is_ascii_whitespace()).to_ascii_uppercase();
    (number.len() == 8 && number.bytes().all(|b| b.is_ascii_alphanumeric()) && number.bytes().any(|b| b.is_ascii_digit())).then_some(number)
}

/// Evidence basis of an assigned identity, independent of reporting attribution.
#[derive(Clone, Copy, Debug, Serialize)]
#[serde(rename_all="snake_case")]
pub enum IdentityBasis { SourceReportedCompany, StatisticalLink, ProvisionalSingleton, Unresolved }
/// One outcome for each input source-role observation.
#[derive(Serialize)]
pub struct ObservationResolution {
    pub(crate) funder_id: FunderObservationId,
    pub(crate) identity_id: Option<String>,
    pub(crate) identity_basis: IdentityBasis,
}
/// Policy disposition of one statistical candidate edge.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all="snake_case")]
pub enum PairDisposition { Accepted, Review, Rejected }
/// A scored edge retained for inspection, including rejected evidence.
#[derive(Serialize)]
pub struct PairDecision {
    pub(crate) left_funder_id: FunderObservationId,
    pub(crate) right_funder_id: FunderObservationId,
    pub(crate) probability: f64,
    pub(crate) name_level: i32,
    pub(crate) address_level: i32,
    pub(crate) disposition: PairDisposition,
    pub(crate) reason: String,
}
/// A selected source role, or an explicit reporting failure.
#[derive(Serialize)]
#[serde(tag="attribution_status", rename_all="snake_case")]
pub enum AttributionDecision {
    Selected { selected_funder_id: FunderObservationId, attribution_basis: String, selected_parent_declaration_id: Option<u32> },
    Unavailable { unavailable_reason: String },
}
/// Exactly one attribution row for one funding occurrence.
#[derive(Serialize)]
pub struct PaymentAttribution {
    pub(crate) funding_entry_id: FundingEntryId,
    #[serde(flatten)]
    pub(crate) decision: AttributionDecision,
    pub(crate) issues: Vec<String>,
}
/// Complete immutable identity, candidate, and payment results.
pub struct ResolvedDeclarations {
    pub(crate) observations: Vec<ObservationResolution>,
    pub(crate) attributions: Vec<PaymentAttribution>,
    pub(crate) pairs: Vec<PairDecision>,
    pub(crate) manifest: serde_json::Value,
}
/// Counts published by one successful resolution operation.
#[derive(Clone, Debug)]
pub struct DeclarationResolutionSummary {
    /// Source observations, including unresolved names.
    pub observations: usize,
    /// Original funding occurrences, counted once.
    pub payments: usize,
    /// Statistical edges retained in the output.
    pub pairs: usize,
}

impl ResolvedDeclarations {
    /// Applies conservative identity links and the independent payment-role policy.
    ///
    /// # Errors
    /// Refuses expansion of repeated profiles beyond the configured candidate budget.
    pub fn from_scored(input: &ResolutionInput, scoring: &ScoringInput, scored: ScoredPairs, run_key: &str) -> Result<Self, EntityIngestionError> {
        let mut edges = BTreeMap::new();
        for pair in scored.pairs {
            for left in &scoring.members[&pair.left] {
                for right in &scoring.members[&pair.right] {
                    if left == right { continue; }
                    let (left,right) = if left < right { (left,right) } else { (right,left) };
                    let a = &input.observations[left]; let b = &input.observations[right];
                    if company(a).is_some() && company(b).is_some() { continue; }
                    edges.entry((left.clone(),right.clone())).or_insert(PairDecision {
                        left_funder_id: left.clone(), right_funder_id: right.clone(), probability: pair.probability,
                        name_level: pair.name_level, address_level: pair.address_level, disposition: PairDisposition::Review, reason: "insufficient_exact_evidence".into(),
                    });
                    if edges.len() > scoring.candidate_budget { return Err(invalid("expanded observation pairs exceed candidate budget; raise candidate_budget explicitly")); }
                }
            }
        }
        let mut components: Vec<BTreeSet<FunderObservationId>> = Vec::new();
        let mut anchors = BTreeMap::<String,usize>::new();
        let mut group = BTreeMap::new();
        for observation in input.observations.values() {
            let index = if let Some(number) = company(observation) {
                *anchors.entry(number).or_insert_with(|| { components.push(BTreeSet::new()); components.len()-1 })
            } else { components.push(BTreeSet::new()); components.len()-1 };
            components[index].insert(observation.funder_id.clone()); group.insert(observation.funder_id.clone(),index);
        }
        let strong = |edge: &PairDecision| {
            let a = &input.observations[&edge.left_funder_id]; let b = &input.observations[&edge.right_funder_id];
            edge.probability >= AUTOMATIC_THRESHOLD && a.name_normalized.is_some() && a.name_normalized == b.name_normalized && a.address_normalized.is_some() && a.address_normalized == b.address_normalized
        };
        let mut candidate_companies = BTreeMap::<FunderObservationId,BTreeSet<String>>::new();
        for edge in edges.values().filter(|edge| strong(edge)) {
            for (unknown,known) in [(&edge.left_funder_id,&edge.right_funder_id),(&edge.right_funder_id,&edge.left_funder_id)] {
                if company(&input.observations[unknown]).is_none() {
                    if let Some(number) = company(&input.observations[known]) { candidate_companies.entry(unknown.clone()).or_default().insert(number); }
                }
            }
        }
        let ambiguous = candidate_companies.iter().filter(|(_,numbers)| numbers.len()>1).map(|(id,_)|id.clone()).collect::<BTreeSet<_>>();
        for edge in edges.values_mut() {
            let a = &input.observations[&edge.left_funder_id]; let b = &input.observations[&edge.right_funder_id];
            if kind(a) != EntityKind::Unknown && kind(b) != EntityKind::Unknown && kind(a) != kind(b) {
                edge.disposition = PairDisposition::Rejected; edge.reason = "person_organisation_conflict".into(); continue;
            }
            if a.address_normalized.is_some() && b.address_normalized.is_some() && a.address_normalized != b.address_normalized {
                edge.disposition = PairDisposition::Rejected; edge.reason = "full_address_disagreement".into(); continue;
            }
            if !strong(edge) { continue; }
            if ambiguous.contains(&edge.left_funder_id) || ambiguous.contains(&edge.right_funder_id) { edge.reason = "competing_company_anchors".into(); continue; }
            let left = group[&edge.left_funder_id]; let right = group[&edge.right_funder_id];
            let ids = components[left].union(&components[right]).cloned().collect::<BTreeSet<_>>();
            let companies = ids.iter().filter_map(|id| company(&input.observations[id])).collect::<BTreeSet<_>>();
            let kinds = ids.iter().map(|id|kind(&input.observations[id])).collect::<Vec<_>>();
            if companies.len()>1 || (kinds.contains(&EntityKind::Person) && kinds.contains(&EntityKind::Organisation)) {
                edge.disposition = PairDisposition::Rejected; edge.reason = "component_identity_conflict".into(); continue;
            }
            if left != right {
                components[right].clear(); components[left] = ids;
                for id in &components[left] { group.insert(id.clone(),left); }
            }
            edge.disposition = PairDisposition::Accepted; edge.reason = "exact_name_full_address_threshold".into();
        }
        let mut observations = Vec::new();
        for observation in input.observations.values() {
            let ids = &components[group[&observation.funder_id]];
            let number = ids.iter().find_map(|id| company(&input.observations[id]));
            let (identity_id,identity_basis) = if let Some(number) = number {
                (Some(format!("source-reported:companies-house:{number}")), if company(observation).is_some() { IdentityBasis::SourceReportedCompany } else { IdentityBasis::StatisticalLink })
            } else if observation.name_normalized.is_none() {
                (None,IdentityBasis::Unresolved)
            } else {
                let leader = serde_json::to_value(ids.first().expect("nonempty component")).map_err(|e|invalid(e.to_string()))?;
                (Some(format!("run-local:{run_key}:{}",leader.as_str().expect("string identity"))), if ids.len()>1 { IdentityBasis::StatisticalLink } else { IdentityBasis::ProvisionalSingleton })
            };
            observations.push(ObservationResolution { funder_id: observation.funder_id.clone(), identity_id, identity_basis });
        }
        let attributions = input.payments.values().map(|payment| attribute(input,payment)).collect::<Vec<_>>();
        let pairs = edges.into_values().collect::<Vec<_>>();
        let manifest = serde_json::json!({ "schema_version":1, "policy_version":POLICY_VERSION, "automatic_threshold":AUTOMATIC_THRESHOLD,
            "input_sha256":input.digests, "model":scored.model, "scoring_profiles":scoring.rows.len(), "observations":observations.len(), "payments":attributions.len(),
            "pair_decisions":pairs.len(), "accepted_pairs":pairs.iter().filter(|p|p.disposition==PairDisposition::Accepted).count(),
            "review_pairs":pairs.iter().filter(|p|p.disposition==PairDisposition::Review).count(), "candidate_budget":scoring.candidate_budget,
            "identity_scope":"run-local IDs use ingestion key and lexicographically first component member; changed membership can change IDs; cross-run reconciliation unsupported" });
        Ok(Self { observations,attributions,pairs,manifest })
    }

    /// Row counts of the complete result.
    #[must_use]
    pub fn summary(&self) -> DeclarationResolutionSummary { DeclarationResolutionSummary { observations:self.observations.len(),payments:self.attributions.len(),pairs:self.pairs.len() } }
}

fn attribute(input: &ResolutionInput, payment: &Payment) -> PaymentAttribution {
    let usable = |id: &FunderObservationId| { let observation=&input.observations[id]; observation.name_normalized.is_some() || company(observation).is_some() };
    let selected = |id: &FunderObservationId, basis: &str, parent| AttributionDecision::Selected { selected_funder_id:id.clone(), attribution_basis:basis.into(), selected_parent_declaration_id:parent };
    let unavailable = |reason: &str| AttributionDecision::Unavailable { unavailable_reason:reason.into() };
    let mut issues=Vec::new();
    let decision = if let Some(id)=&payment.ultimate_payer_funder_id {
        if payment.is_ultimate_payer_different == Some(false) { issues.push("explicit_ultimate_payer_with_parent_payer_same_flag".into()); }
        if usable(id) { selected(id,"explicit_ultimate_payer",None) } else { unavailable("explicit_ultimate_payer_unavailable") }
    } else if payment.is_ultimate_payer_different == Some(true) { unavailable("different_ultimate_payer_unnamed")
    } else if payment.is_ultimate_payer_different == Some(false) {
        if parent_cycle(input,payment) { unavailable("parent_cycle") }
        else if let Some(parent)=payment.parent_declaration_id {
            let candidates=input.observations.values().filter(|o| o.member_id==payment.member_id && o.declaration_id==parent && o.role==FunderRole::Payer && is_root(&o.source_pointer)).collect::<Vec<_>>();
            match candidates.as_slice() {
                [payer] if usable(&payer.funder_id) => selected(&payer.funder_id,"parent_payer",Some(parent)),
                [_] => unavailable("parent_payer_unavailable"),
                [] => unavailable("parent_evidence_unavailable"),
                _ => unavailable("parent_payer_ambiguous"),
            }
        } else { unavailable("parent_evidence_unavailable") }
    } else if let Some(id)=&payment.donor_funder_id {
        if usable(id) { selected(id,"donor",None) } else { unavailable("donor_unavailable") }
    } else if let Some(id)=&payment.payer_funder_id {
        if usable(id) { selected(id,"payer",None) } else { unavailable("payer_unavailable") }
    } else { unavailable("no_supported_attribution") };
    PaymentAttribution { funding_entry_id:payment.funding_entry_id.clone(),decision,issues }
}
fn parent_cycle(input: &ResolutionInput, payment: &Payment) -> bool {
    let mut seen=BTreeSet::new(); let mut next=Some(payment.declaration_id);
    while let Some(id)=next {
        if !seen.insert(id) { return true; }
        next=input.payments.values().find(|p|p.member_id==payment.member_id && p.declaration_id==id).and_then(|p|p.parent_declaration_id);
    }
    false
}

