//! Boundaries for checked cleaned evidence, statistical scores, and complete output.
use super::entity_ingestion::EntitySearchPipelineError;
use crate::domain::models::{declaration_resolution::{ResolutionInput, ScoringInput, ScoredPairs, ResolvedDeclarations}, entity_ingestion::EntityIngestionError};

