use super::{ExposedDataPipeline,declaration_cleaning::{funders_schema,funding_schema,write_table}};
use crate::domain::{models::{declaration_resolution::{Observation,Payment,ResolutionInput,ResolvedDeclarations,ScoringInput,ScoredPair,ScoredPairs},entity_ingestion::EntityIngestionError},repositories::{declaration_resolution::{DeclarationResolutionStorage,FunderScorer},entity_ingestion::EntitySearchPipelineError}};

impl DeclarationResolutionStorage for ExposedDataPipeline {
    async fn read_resolution_input(&self)->Result<ResolutionInput,EntityIngestionError> {
        let destination=self.resolved_declarations_path();
        if destination.exists() { return Err(write_error("resolved declarations already exist").into()); }
        let directory=self.cleaned_declarations_path();
        let (observations,observation_digest)=read_table::<Observation>(&directory.join("funders.parquet"),&funders_schema())?;
        let (payments,payment_digest)=read_table::<Payment>(&directory.join("funding_entries.parquet"),&funding_schema())?;
        ResolutionInput::new(observations,payments,BTreeMap::from([("funders.parquet".into(),observation_digest),("funding_entries.parquet".into(),payment_digest)]))
    }
    fn resolution_run_key(&self)->String { crate::domain::models::entity_ingestion::IngestionKey::from(self.key()).to_string() }
    async fn publish_resolution(&self,result:&ResolvedDeclarations)->Result<(),EntitySearchPipelineError> {
        let destination=self.resolved_declarations_path();
        let parent=destination.parent().expect("resolved declarations have a parent");
        fs::create_dir_all(parent).await.map_err(write_error)?;
        let lock_path=parent.join(".declarations-publication.lock");
        let lock=fs::File::create_new(&lock_path).await.map_err(|error|write_error(format!("cannot acquire declaration publication lock {}: {error}",lock_path.display())))?;
        let staging=parent.join(format!(".declarations-{}",Uuid::now_v7()));
        let publication=async {
            if fs::try_exists(&destination).await.map_err(write_error)? { return Err(write_error("resolved declarations already exist")); }
            fs::create_dir(&staging).await.map_err(write_error)?;
            write_table(&staging.join("observation_resolution.parquet"),observation_schema(),&result.observations).await?;
            write_table(&staging.join("payment_attribution.parquet"),attribution_schema(),&result.attributions).await?;
            write_table(&staging.join("pair_decisions.parquet"),pair_schema(),&result.pairs).await?;
            fs::write(staging.join("manifest.json"),serde_json::to_vec_pretty(&result.manifest).map_err(write_error)?).await.map_err(write_error)?;
            fs::rename(&staging,&destination).await.map_err(write_error)
        }.await;
        if publication.is_err() { let _=fs::remove_dir_all(&staging).await; }
        drop(lock);
        let removal=fs::remove_file(&lock_path).await.map_err(write_error);
        publication.and(removal)
    }
}

fn read_table<T:DeserializeOwned>(path:&Path,expected:&Schema)->Result<(Vec<T>,String),EntitySearchPipelineError> {
    let bytes=std::fs::read(path).map_err(read_error)?;
    let digest=format!("{:x}",Sha256::digest(&bytes));
    let reader=ParquetRecordBatchReaderBuilder::try_new(bytes::Bytes::from(bytes)).map_err(read_error)?;
    for required in expected.fields() {
        let actual=reader.schema().field_with_name(required.name()).map_err(|_|read_error("cleaned declarations lack the resolution schema; clean the retained raw capture into a fresh ingestion run"))?;
        if actual.data_type()!=required.data_type() || actual.is_nullable()!=required.is_nullable() { return Err(read_error(format!("cleaned field {} has an incompatible type; clean retained raw into a fresh run",required.name()))); }
    }
    let mut rows=Vec::new();
    for batch in reader.build().map_err(read_error)? {
        let mut writer=ArrayWriter::new(Vec::new()); writer.write(&batch.map_err(read_error)?).map_err(read_error)?; writer.finish().map_err(read_error)?;
        rows.extend(serde_json::from_slice::<Vec<T>>(&writer.into_inner()).map_err(read_error)?);
    }
    Ok((rows,digest))
}

/// Python subprocess adapter for the pinned Splink worker.
pub struct SplinkScorer { python:PathBuf,worker:PathBuf }
impl SplinkScorer {
    /// Selects the interpreter and the separately installed worker script.
    ///
    /// # Errors
    /// Returns an error when the configured worker cannot be read.
    pub fn new(python:PathBuf,worker:PathBuf)->Result<Self,EntityIngestionError> {
        if !worker.is_file() { return Err(EntityIngestionError::DataError(format!("Splink worker missing at {}; configure resolution_worker",worker.display()))); }
        Ok(Self {python,worker})
    }
}
#[derive(Deserialize)]
struct WorkerOutput { version:u32,model:serde_json::Value,pairs:Vec<ScoredPair> }
impl FunderScorer for SplinkScorer {
    async fn score(&self,input:&ScoringInput)->Result<ScoredPairs,EntityIngestionError> {
        let encoded=serde_json::to_vec(input).map_err(|e|EntityIngestionError::DataError(e.to_string()))?;
        let python=self.python.clone(); let worker=self.worker.clone();
        let output=tokio::task::spawn_blocking(move || -> Result<WorkerOutput,EntityIngestionError> {
            let temporary=tempfile::tempdir().map_err(|e|EntityIngestionError::DataError(e.to_string()))?;
            let request=temporary.path().join("input.json"); let response=temporary.path().join("output.json");
            std::fs::write(&request,encoded).map_err(|e|EntityIngestionError::DataError(e.to_string()))?;
            let process=Command::new(&python).arg(&worker).arg(&request).arg(&response).env("PYTHONDONTWRITEBYTECODE","1").output().map_err(|e|EntityIngestionError::DataError(format!("cannot run Splink interpreter {}: {e}; install resolution dependencies before running resolve",python.display())))?;
            if !process.status.success() { return Err(EntityIngestionError::DataError(format!("Splink worker failed ({}): {}",process.status,String::from_utf8_lossy(&process.stderr)))); }
            let bytes=std::fs::read(&response).map_err(|e|EntityIngestionError::DataError(format!("Splink worker output missing: {e}")))?;
            serde_json::from_slice(&bytes).map_err(|e|EntityIngestionError::DataError(format!("invalid Splink worker output: {e}")))
        }).await.map_err(|e|EntityIngestionError::DataError(e.to_string()))??;
        if output.version!=1 || output.model["model_version"]!="funder-frozen-v1" || output.model["splink_version"]!="4.0.17" || output.model["calibrated"]!=false {
            return Err(EntityIngestionError::DataError("unsupported Splink protocol, model, or runtime version".into()));
        }
        ScoredPairs::checked(output.pairs,output.model,input)
    }
}
