use super::*;

fn observation(id:u32,name:Option<&str>,address:Option<&str>,kind:Option<&str>,company:Option<&str>)->Observation {
    Observation { funder_id: serde_json::from_value(serde_json::json!(format!("00000000-0000-0000-0000-000000000001/{id}/1/declaration/donor"))).unwrap(), member_id:"00000000-0000-0000-0000-000000000001".into(), declaration_id:id,register_id:1,role:FunderRole::Donor,source_scope:"declaration".into(),source_pointer:"/versions/0/fields".into(),funding_entry_id:None,funding_ordinal:None,donor_kind:kind.map(str::to_owned),donor_company_number:company.map(str::to_owned),name_normalized:name.map(str::to_owned),address_normalized:address.map(str::to_owned) }
}
fn input(observations:Vec<Observation>)->ResolutionInput { ResolutionInput::new(observations,Vec::new(),BTreeMap::new()).unwrap() }
fn resolve(input:&ResolutionInput,probability:f64)->ResolvedDeclarations {
    let scoring=input.scoring_input(100);
    let pairs=scoring.rows.iter().enumerate().flat_map(|(index,left)|scoring.rows[index+1..].iter().map(move |right|ScoredPair {left:left.key.clone(),right:right.key.clone(),probability,name_level:2,address_level:1})).collect();
    let scored=ScoredPairs::checked(pairs,serde_json::json!({"calibrated":false}),&scoring).unwrap();
    ResolvedDeclarations::from_scored(input,&scoring,scored,"test-run").unwrap()
}
#[test]
fn noncompanies_share_only_exact_name_full_address() {
    let result=resolve(&input(vec![observation(1,Some("john smith"),Some("1 road"),Some("Individual"),None),observation(2,Some("john smith"),Some("1 road"),Some("Individual"),None),observation(3,Some("john smith"),Some("2 road"),Some("Individual"),None)]),0.9999);
    assert_eq!(result.observations[0].identity_id,result.observations[1].identity_id);
    assert_ne!(result.observations[0].identity_id,result.observations[2].identity_id);
    assert!(result.pairs.iter().any(|edge|edge.disposition==PairDisposition::Rejected));
}
#[test]
fn fuzzy_and_name_only_remain_review_and_singletons() {
    for address in [None,Some("1 road")] {
        let result=resolve(&input(vec![observation(1,Some("john smith"),address,None,None),observation(2,Some(if address.is_some(){"jon smith"}else{"john smith"}),address,None,None)]),0.9999);
        assert_ne!(result.observations[0].identity_id,result.observations[1].identity_id);
        assert!(result.pairs.iter().all(|edge|edge.disposition==PairDisposition::Review));
    }
}
#[test]
fn ambiguous_company_attachment_does_not_bridge() {
    let result=resolve(&input(vec![observation(1,Some("acme"),Some("1 road"),Some("Company"),Some("00000001")),observation(2,Some("acme"),Some("1 road"),None,None),observation(3,Some("acme"),Some("1 road"),Some("Company"),Some("00000002"))]),0.9999);
    assert_eq!(result.observations[0].identity_id.as_deref(),Some("source-reported:companies-house:00000001"));
    assert_eq!(result.observations[2].identity_id.as_deref(),Some("source-reported:companies-house:00000002"));
    assert!(result.observations[1].identity_id.as_ref().unwrap().starts_with("run-local:"));
    assert!(result.pairs.iter().all(|edge|edge.disposition==PairDisposition::Review));
}
#[test]
fn explicit_person_kind_cannot_anchor_or_join_company() {
    let result=resolve(&input(vec![observation(1,Some("smith"),Some("1 road"),Some("Individual"),Some("00000001")),observation(2,Some("smith"),Some("1 road"),Some("Company"),Some("00000001"))]),0.9999);
    assert_ne!(result.observations[0].identity_id,result.observations[1].identity_id);
    assert_eq!(result.pairs[0].disposition,PairDisposition::Rejected);
}
#[test]
fn company_parser_preserves_conservative_source_policy() {
    for (raw,expected) in [(" sc012345 ",Some("SC012345")),("527227",None),("NI 016363",None),("AAAAAAAA",None),("00527227",Some("00527227"))] {
        assert_eq!(company(&observation(1,None,None,None,Some(raw))).as_deref(),expected);
    }
    let result=resolve(&input(vec![observation(1,None,None,None,Some("00527227")),observation(2,None,None,None,None)]),0.9999);
    assert!(result.observations[0].identity_id.is_some()); assert!(result.observations[1].identity_id.is_none());
}
