fn reordered_input_produces_identical_results() {
    let observations=vec![observation(1,Some("charity"),Some("1 road"),Some("Charity"),None),observation(2,Some("charity"),Some("1 road"),Some("Charity"),None)];
    let mut reverse=observations.clone(); reverse.reverse();
    let a=resolve(&input(observations),0.9999);let b=resolve(&input(reverse),0.9999);
