use exposed::{domain::{models::{declaration_ingestion::{CapturedDeclaration,CapturedFundingEntry,DeclarationId,MemberAsId},entity_ingestion::IngestionKey},repositories::entity_ingestion::EntityIngestionStorage},outbound::ExposedDataPipeline};
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use serde_json::{Value,json};
use uuid::Uuid;

fn rows(path:&Path)->anyhow::Result<Vec<Value>> {
    let reader=ParquetRecordBatchReaderBuilder::try_new(fs::File::open(path)?)?.build()?;
    let mut rows=Vec::new();
    for batch in reader {let mut writer=ArrayWriter::new(Vec::new());writer.write(&batch?)?;writer.finish()?;rows.extend(serde_json::from_slice::<Vec<Value>>(&writer.into_inner())?);}
    Ok(rows)
}
fn run(stage:&str,config:&Path,key:&IngestionKey)->std::process::Output {
    Command::new(env!("CARGO_BIN_EXE_exposed")).args(["data","declarations",stage]).arg(config).arg("--ingestion-key").arg(key.to_string()).env_remove("DATABASE_URL").output().unwrap()
}
#[tokio::test]
#[ignore="requires built CLI, SQLx compile-time database, and EXPOSED_RESOLUTION_PYTHON with pinned Splink"]
async fn clean_then_resolve_with_real_splink_preserves_occurrences_and_refuses_overwrite()->anyhow::Result<()> {
    let python=std::env::var("EXPOSED_RESOLUTION_PYTHON")?;
    let temporary=tempfile::tempdir()?;
    let key=IngestionKey::default();
    let root=temporary.path().join("data");
    let storage=ExposedDataPipeline::new_with_ingestion_key(&root,key.clone())?;
    let member=MemberAsId::new(Uuid::from_u128(1),1)?;
    let date=NaiveDate::from_ymd_opt(2026,9,7).unwrap();
    let mut captures=Vec::new();
    for id in 1..=2 {
        let source=json!({"id":id,"category":{"id":3,"name":"Donations"},"versions":[{"register":{"id":820,"publishedDate":"2026-09-07"},"fields":[{"name":"DonorName","value":"Example Charity"},{"name":"DonorStatus","value":"Charity"},{"name":"DonorPublicAddress","value":"10 Example Road, London SW1A 1AA"},{"name":"Value","value":"100"}]}]});
        captures.push(CapturedDeclaration::new(DeclarationId::new(id)?,None,3,"Donations".into(),820,date,None,vec![CapturedFundingEntry::new(None,Some("Example Charity".into()),None,Some("100".into()),None,None,Some("Charity".into()),None,None)],Utc::now(),source.to_string())?);
    }
    storage.write_raw_declarations(member,&captures).await?;
    let config=temporary.path().join("resolution.yaml");
    let worker=Path::new(env!("CARGO_MANIFEST_DIR")).join("../resolution/worker.py");
    fs::write(&config,format!("data_dir: {}\nresolution_python: {}\nresolution_worker: {}\ncandidate_budget: 100\n",serde_json::to_string(&root)?,serde_json::to_string(&python)?,serde_json::to_string(&worker)?))?;
    let clean=run("clean",&config,&key);assert!(clean.status.success(),"{}",String::from_utf8_lossy(&clean.stderr));
    let cleaned=root.join(key.to_string()).join("cleaned/declarations");
    let before=fs::read(cleaned.join("funders.parquet"))?;
    fs::remove_dir_all(root.join(key.to_string()).join("raw"))?;
    let resolved=run("resolve",&config,&key);assert!(resolved.status.success(),"{}",String::from_utf8_lossy(&resolved.stderr));
    let output=root.join(key.to_string()).join("resolved/declarations");
    let observations=rows(&output.join("observation_resolution.parquet"))?;
    assert_eq!(observations.len(),2);
    assert_eq!(observations.iter().map(|r|r["identity_id"].as_str().unwrap()).collect::<BTreeSet<_>>().len(),1);
    assert!(observations.iter().all(|row|row["identity_basis"]=="statistical_link"));
    let attribution=rows(&output.join("payment_attribution.parquet"))?;
    assert_eq!(attribution.len(),2);assert!(attribution.iter().all(|row|row["attribution_basis"]=="donor"));
    let pairs=rows(&output.join("pair_decisions.parquet"))?;assert_eq!(pairs.len(),1);assert_eq!(pairs[0]["disposition"],"accepted");
    let manifest=fs::read(output.join("manifest.json"))?;
    let model:Value=serde_json::from_slice(&manifest)?;assert_eq!(model["model"]["splink_version"],"4.0.17");assert_eq!(model["model"]["calibrated"],false);
    assert_eq!(fs::read(cleaned.join("funders.parquet"))?,before);
    assert!(!run("resolve",&config,&key).status.success());assert_eq!(fs::read(output.join("manifest.json"))?,manifest);
    Ok(())
}
RS
