#[test]
fn atomic_directory_publication_refuses_an_existing_empty_directory() {
    let temporary=tempfile::tempdir().unwrap();
    let staging=temporary.path().join("staging");let destination=temporary.path().join("destination");
    std::fs::create_dir(&staging).unwrap();std::fs::write(staging.join("evidence"),"retained").unwrap();std::fs::create_dir(&destination).unwrap();
    assert!(publish_directory(&staging,&destination).is_err());assert!(staging.join("evidence").is_file());assert_eq!(std::fs::read_dir(&destination).unwrap().count(),0);
}

#[tokio::test]
async fn malformed_worker_output_is_rejected_at_the_process_boundary() {
    let temporary=tempfile::tempdir().unwrap();let path=temporary.path().join("worker.py");
    for content in ["not json",r#"{"version":99,"model":{},"pairs":[]}"#] {
        std::fs::write(&path,format!("import sys\nwith open(sys.argv[2], 'w') as f: f.write({content:?})\n")).unwrap();
        let scorer=SplinkScorer::new(PathBuf::from("python3"),path.clone()).unwrap();
        let input=ResolutionInput::new(vec![],vec![],BTreeMap::new()).unwrap();assert!(scorer.score(&input.scoring_input(10)).await.is_err());
    }
}

#[tokio::test]
async fn failed_publication_removes_staging_and_never_creates_final_output() {
    let temporary=tempfile::tempdir().unwrap();
    let storage=ExposedDataPipeline::new_with_ingestion_key(&temporary.path().to_path_buf(),IngestionKey::default()).unwrap();
    let destination=storage.resolved_declarations_path();let parent=destination.parent().unwrap();fs::create_dir_all(parent).await.unwrap();
    fs::write(&destination,b"existing file").await.unwrap();
    let result=ResolvedDeclarations {observations:vec![],attributions:vec![],pairs:vec![],manifest:serde_json::json!({})};
    assert!(storage.publish_resolution(&result).await.is_err());assert_eq!(fs::read(&destination).await.unwrap(),b"existing file");
    assert_eq!(std::fs::read_dir(parent).unwrap().count(),1);
}
