#[test]
fn parent_cycles_and_true_or_absent_flags_never_inherit_payer() {
    let mut payer=observation(1,Some("guardian"),None,None,None);payer.role=FunderRole::Payer;
    payer.funder_id=serde_json::from_value(serde_json::json!(payer.funder_id.as_str().replace("donor","payer"))).unwrap();
    for flag in [None,Some(true)] {
        let child=payment(2,Some(1),flag);let input=ResolutionInput::new(vec![payer.clone()],vec![child.clone()],BTreeMap::new()).unwrap();
        assert!(matches!(attribute(&input,&child).decision,AttributionDecision::Unavailable {..}));
    }
    let parent=payment(1,Some(2),None);let child=payment(2,Some(1),Some(false));
    let input=ResolutionInput::new(vec![payer],vec![parent,child.clone()],BTreeMap::new()).unwrap();
    assert!(matches!(attribute(&input,&child).decision,AttributionDecision::Unavailable {unavailable_reason:UnavailableReason::ParentCycle}));
}

#[test]
fn duplicate_occurrences_remain_separate_and_profile_grouping_does_not_merge_names() {
    let mut first=payment(1,None,None);let mut second=first.clone();second.funding_ordinal=1;
    second.funding_entry_id=serde_json::from_value(serde_json::json!(format!("{}/{}/{}/funding/1",second.member_id,second.declaration_id,second.register_id))).unwrap();
    let mut observations=Vec::new();
    for occurrence in [&mut first,&mut second] {
        let mut donor=observation(1,Some("john smith"),None,Some("Individual"),None);
        donor.source_scope="funding_entry".into();donor.funding_ordinal=Some(occurrence.funding_ordinal);donor.funding_entry_id=Some(occurrence.funding_entry_id.clone());
        donor.funder_id=serde_json::from_value(serde_json::json!(format!("{}/donor",occurrence.funding_entry_id.as_str()))).unwrap();
        occurrence.donor_funder_id=Some(donor.funder_id.clone());observations.push(donor);
    }
    let input=ResolutionInput::new(observations,vec![first,second],BTreeMap::new()).unwrap();let result=resolve(&input,0.9999);
    assert_eq!(result.attributions.len(),2);assert_eq!(result.observations.len(),2);assert_eq!(result.pairs.len(),1);
    assert_ne!(result.observations[0].identity_id,result.observations[1].identity_id);
    assert_eq!(result.pairs[0].disposition,PairDisposition::Review);
}
